package org.solaris.receiver;
import android.content.*;import android.graphics.Rect;import android.media.MediaCodecInfo;import android.media.MediaCodecList;import android.media.projection.MediaProjection;import android.view.WindowManager;import org.webrtc.*;import org.json.*;import java.util.*;import java.util.function.Consumer;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;
final class ScreenEngine {
 private final Context context;private final BroadcastSignals signals;private final NativeDiagnostics diagnostics;private final Consumer<JSONObject> emit;private final ScheduledExecutorService queue=Executors.newSingleThreadScheduledExecutor();private final Map<String,Node> peers=new HashMap<>();private final AtomicLong frames=new AtomicLong();private volatile boolean closed;
 private JSONObject scope,options;private EglBase egl;private PeerConnectionFactory factory;private ScreenCapturerAndroid capture;private VideoSource source;private VideoTrack track;private SurfaceTextureHelper helper;private volatile String id;private int captureWidth,captureHeight,captureFPS=60;private Consumer<Exception> startReady;private List<PeerConnection.IceServer> ice=new ArrayList<>();
 private static final class Node {final String viewer,connection=UUID.randomUUID().toString();String broadcast,offer;PeerConnection pc;boolean ready;JSONObject quality;long seen=System.currentTimeMillis();final List<IceCandidate> pending=new ArrayList<>();Node(String viewer){this.viewer=viewer;}}
 ScreenEngine(Context c,DiskBridge disk,Consumer<JSONObject> out){context=c;emit=out;diagnostics=new NativeDiagnostics(c);
 signals=new BroadcastSignals(new BroadcastSignals.Vault(){public JSONObject load()throws Exception{Object raw=disk.command("vaultGet",new JSONObject().put("key","session"));return raw==null?null:new JSONObject((String)raw);}public void save(JSONObject value)throws Exception{disk.command("vaultSet",new JSONObject().put("key","session").put("value",value.toString()));}},new BroadcastSignals.Listener(){public void snapshot(String broadcast,JSONObject value){post(()->{if(Objects.equals(id,broadcast))prune(value);});}public void signal(JSONObject value){post(()->incoming(value));}public void ended(String broadcast,String reason){post(()->{if(Objects.equals(id,broadcast))end(new Exception(reason));});}public void error(Exception error){peerError("signaling",error);}});
 queue.scheduleAtFixedRate(()->guard(()->{for(Iterator<Node> it=peers.values().iterator();it.hasNext();){Node n=it.next();if(System.currentTimeMillis()-n.seen>45000){it.remove();dispose(n);}}}),5,5,TimeUnit.SECONDS);
 }
 private void initialize(){if(factory!=null)return;PeerConnectionFactory.initialize(PeerConnectionFactory.InitializationOptions.builder(context).createInitializationOptions());egl=EglBase.create();
 // Prefer hardware H264 baseline. Keep VP8/software fallback, without advertising
 // the high-profile codec that some Android hardware cannot initialize reliably.
 DefaultVideoEncoderFactory delegate=new DefaultVideoEncoderFactory(egl.getEglBaseContext(),true,false);
 VideoEncoderFactory encoder=new VideoEncoderFactory(){public VideoEncoder createEncoder(VideoCodecInfo info){return delegate.createEncoder(info);}public VideoCodecInfo[] getSupportedCodecs(){VideoCodecInfo[] codecs=delegate.getSupportedCodecs();Arrays.sort(codecs,Comparator.comparingInt(c->c.name.equalsIgnoreCase("H264")?0:1));return codecs;}};
 factory=PeerConnectionFactory.builder().setVideoEncoderFactory(encoder).setVideoDecoderFactory(new DefaultVideoDecoderFactory(egl.getEglBaseContext())).createPeerConnectionFactory();}
 private int[] supportedSize(int width,int height){int[] target=CaptureGeometry.fit(width,height,2560,1440);try{List<MediaCodecInfo.VideoCapabilities> encoders=new ArrayList<>();for(MediaCodecInfo codec:new MediaCodecList(MediaCodecList.REGULAR_CODECS).getCodecInfos())if(codec.isEncoder()&&codec.isHardwareAccelerated())for(String type:codec.getSupportedTypes())if(type.equalsIgnoreCase("video/avc"))encoders.add(codec.getCapabilitiesForType(type).getVideoCapabilities());
 // Keep 60fps where the hardware explicitly supports it, with the actual ratio.
 for(double factor:new double[]{1,.9,.8,.75,.6666667,.5}){int w=Math.max(2,(int)(target[0]*factor)/2*2),h=Math.max(2,(int)(target[1]*factor)/2*2);for(MediaCodecInfo.VideoCapabilities caps:encoders)if(caps.areSizeAndRateSupported(w,h,60))return new int[]{w,h};}
 }catch(Exception error){diagnostics.record("codec-capabilities",error);}return CaptureGeometry.fit(width,height,1920,1080);}
 void start(Intent permission,JSONObject args,Consumer<Exception> ready){post(()->{try{stopInternal();initialize();scope=args.getJSONObject("scope");id=args.getString("id");options=args.getJSONObject("quality");startReady=ready;frames.set(0);ice=new ArrayList<>();JSONArray list=args.optJSONArray("iceServers");if(list!=null)for(int i=0;i<list.length();i++){JSONObject s=list.getJSONObject(i);List<String> urls=new ArrayList<>();Object u=s.get("urls");if(u instanceof JSONArray){JSONArray arr=(JSONArray)u;for(int j=0;j<arr.length();j++)urls.add(arr.getString(j));}else urls.add((String)u);ice.add(PeerConnection.IceServer.builder(urls).setUsername(s.optString("username")).setPassword(s.optString("credential")).createIceServer());}
 Rect bounds=context.getSystemService(WindowManager.class).getMaximumWindowMetrics().getBounds();int[] size=supportedSize(bounds.width(),bounds.height());captureWidth=size[0];captureHeight=size[1];captureFPS=60;source=factory.createVideoSource(true);source.adaptOutputFormat(captureWidth,captureHeight,captureFPS);track=factory.createVideoTrack("solaris-screen",source);helper=SurfaceTextureHelper.create("SolarisScreen",egl.getEglBaseContext());final String captureId=id;
 capture=new ScreenCapturerAndroid(permission,new MediaProjection.Callback(){@Override public void onStop(){post(()->{if(Objects.equals(id,captureId))end(null);});}@Override public void onCapturedContentResize(int width,int height){post(()->{if(Objects.equals(id,captureId))resize(width,height);});}});
 CapturerObserver observer=source.getCapturerObserver();capture.initialize(helper,context,new CapturerObserver(){public void onCapturerStarted(boolean success){observer.onCapturerStarted(success);}public void onCapturerStopped(){observer.onCapturerStopped();}public void onFrameCaptured(VideoFrame frame){if(closed||!Objects.equals(id,captureId))return;observer.onFrameCaptured(frame);if(frames.incrementAndGet()==1)post(()->{if(!Objects.equals(id,captureId)||startReady==null)return;try{signals.start(args);Consumer<Exception> callback=startReady;startReady=null;callback.accept(null);}catch(Exception error){diagnostics.record("capture-ready",error);end(error);}});}});
 capture.startCapture(captureWidth,captureHeight,captureFPS);queue.schedule(()->guard(()->{if(Objects.equals(id,captureId)&&startReady!=null)end(new Exception("화면 캡처 프레임이 도착하지 않았습니다. 화면공유를 다시 시작하세요."));}),8,TimeUnit.SECONDS);
 }catch(Exception error){diagnostics.record("capture-start",error);startReady=null;stopInternal();ready.accept(error);}});}
 private void resize(int width,int height){if(capture==null||width<=0||height<=0)return;int[] size=supportedSize(width,height);if(size[0]==captureWidth&&size[1]==captureHeight)return;captureWidth=size[0];captureHeight=size[1];
 // M144 resizes the existing virtual display on Android 12+, without consuming
 // a MediaProjection consent token a second time on Android 14+.
 capture.changeCaptureFormat(captureWidth,captureHeight,captureFPS);source.adaptOutputFormat(captureWidth,captureHeight,captureFPS);}
 void displayChanged(){post(()->{if(capture==null)return;Rect r=context.getSystemService(WindowManager.class).getMaximumWindowMetrics().getBounds();resize(r.width(),r.height());});}
 void command(String command,JSONObject args){post(()->{try{if(id==null||!id.equals(args.optString("id")))return;String viewer=args.optString("viewerID");Node n=peers.get(viewer);if(command.equals("mediaJoin")||command.equals("mediaRecover")){if(n!=null){if(command.equals("mediaJoin")){n.seen=System.currentTimeMillis();if(n.offer!=null)signal(n,new JSONObject().put("type","native-offer").put("sdp",n.offer));return;}if(!n.connection.equals(args.optString("connectionID")))return;peers.remove(viewer);dispose(n);}if(peers.size()>=5)throw new Exception("시청자는 최대 5명입니다.");join(viewer);return;}if(n==null||!n.connection.equals(args.optString("connectionID")))return;n.seen=System.currentTimeMillis();
 if(command.equals("mediaAnswer")){final Node selected=n;n.pc.setRemoteDescription(new Observer(n){@Override public void onSetSuccess(){post(()->{if(peers.get(selected.viewer)!=selected)return;selected.ready=true;for(IceCandidate candidate:selected.pending)selected.pc.addIceCandidate(candidate);selected.pending.clear();quality(selected,selected.quality);});}},new SessionDescription(SessionDescription.Type.ANSWER,args.getString("sdp")));}
 else if(command.equals("mediaIce")){IceCandidate candidate=new IceCandidate(args.optString("sdpMid","0"),args.optInt("sdpMLineIndex"),args.getString("candidate"));if(n.ready)n.pc.addIceCandidate(candidate);else if(n.pending.size()<128)n.pending.add(candidate);}else if(command.equals("mediaLeave")){peers.remove(viewer);dispose(n);}else if(command.equals("mediaQuality")){n.quality=args.optJSONObject("quality");if(n.ready)quality(n,n.quality);}
 }catch(Exception error){peerError("peer-command",error);}});}
 private void join(String viewer)throws Exception{if(track==null||frames.get()==0)throw new Exception("화면 캡처 준비 중입니다.");Node n=new Node(viewer);n.broadcast=id;PeerConnection.RTCConfiguration rtc=new PeerConnection.RTCConfiguration(ice);rtc.sdpSemantics=PeerConnection.SdpSemantics.UNIFIED_PLAN;
 n.pc=factory.createPeerConnection(rtc,new PeerConnection.Observer(){public void onSignalingChange(PeerConnection.SignalingState s){}public void onIceConnectionChange(PeerConnection.IceConnectionState s){}public void onIceConnectionReceivingChange(boolean r){}public void onIceGatheringChange(PeerConnection.IceGatheringState s){}public void onIceCandidate(IceCandidate candidate){try{signal(n,new JSONObject().put("type","native-ice").put("candidate",new JSONObject().put("candidate",candidate.sdp).put("sdpMid",candidate.sdpMid).put("sdpMLineIndex",candidate.sdpMLineIndex)));}catch(Exception error){peerError("peer-ice",error);}}public void onIceCandidatesRemoved(IceCandidate[] c){}public void onAddStream(MediaStream s){}public void onRemoveStream(MediaStream s){}public void onDataChannel(DataChannel d){d.close();}public void onRenegotiationNeeded(){}public void onAddTrack(RtpReceiver r,MediaStream[] s){} });
 if(n.pc==null)throw new Exception("WebRTC 생성 실패");peers.put(viewer,n);try{if(n.pc.addTrack(track,List.of("solaris"))==null)throw new Exception("화면 트랙을 연결하지 못했습니다.");n.pc.createOffer(new Observer(n){@Override public void onCreateSuccess(SessionDescription description){post(()->{if(peers.get(n.viewer)!=n)return;n.pc.setLocalDescription(new Observer(n){@Override public void onSetSuccess(){post(()->{if(peers.get(n.viewer)!=n)return;try{n.offer=description.description;signal(n,new JSONObject().put("type","native-offer").put("sdp",n.offer));}catch(Exception error){peerError("peer-offer",error);}});}},description);});}},new MediaConstraints());}catch(Exception error){peers.remove(viewer);dispose(n);throw error;}}
 private void quality(Node n,JSONObject q){int requested=Math.max(8,Math.min(25,q==null?25:q.optInt("mbps",25))),bitrate=(requested>=25?60:requested)*1000000;for(RtpSender sender:n.pc.getSenders())if(sender.track()!=null&&sender.track().kind().equals("video")){RtpParameters parameters=sender.getParameters();if(parameters.encodings.isEmpty())continue;for(RtpParameters.Encoding encoding:parameters.encodings){encoding.active=true;encoding.minBitrateBps=Math.min(12000000,bitrate);encoding.maxBitrateBps=bitrate;encoding.maxFramerate=60;encoding.scaleResolutionDownBy=1.0;encoding.bitratePriority=4.0;}parameters.degradationPreference=RtpParameters.DegradationPreference.DISABLED;if(!sender.setParameters(parameters))peerError("encoder-parameters",new Exception("고화질 인코더 설정이 거절되었습니다."));}}
 private void signal(Node n,JSONObject payload){post(()->{if(peers.get(n.viewer)!=n||!Objects.equals(id,n.broadcast))return;try{payload.put("broadcast",n.broadcast).put("connectionID",n.connection);signals.send(n.broadcast,n.viewer,payload);emit.accept(new JSONObject().put("type","media-signal").put("id",n.broadcast).put("viewerID",n.viewer).put("payload",payload));}catch(Exception error){peerError("peer-signal",error);}});}
 private void peerError(String stage,Exception error){diagnostics.record(stage,error);try{emit.accept(new JSONObject().put("type","media-peer-error").put("id",id).put("error",error.getMessage()));}catch(Exception ignored){}}
 private void end(Exception error){String old=id;Consumer<Exception> callback=startReady;startReady=null;stopInternal();if(callback!=null)callback.accept(error==null?new Exception("화면공유가 중지되었습니다."):error);try{JSONObject event=new JSONObject().put("type","media-ended").put("id",old);if(error!=null)event.put("error",error.getMessage());emit.accept(event);}catch(Exception ignored){}}
 void status(Consumer<JSONObject> callback){post(()->{try{JSONArray list=new JSONArray();for(Node n:peers.values())list.put(new JSONObject().put("viewerID",n.viewer).put("connectionID",n.connection));callback.accept(new JSONObject().put("id",id==null?JSONObject.NULL:id).put("active",id!=null&&track!=null&&frames.get()>0).put("nativeSignaling",true).put("peers",list).put("width",captureWidth).put("height",captureHeight).put("fpsTarget",captureFPS).put("framesSubmitted",frames.get()).put("errors",diagnostics.read()));}catch(Exception error){peerError("status",error);}});}
 void stop(){post(()->{Consumer<Exception> callback=startReady;startReady=null;stopInternal();if(callback!=null)callback.accept(new Exception("화면공유가 중지되었습니다."));});}
 void close(){if(closed)return;closed=true;signals.close();try{queue.execute(()->{stopInternal();if(factory!=null)safe("factory-dispose",factory::dispose);if(egl!=null)safe("egl-release",egl::release);queue.shutdown();});}catch(RejectedExecutionException ignored){}}
 private void dispose(Node n){if(n.pc==null)return;PeerConnection peer=n.pc;n.pc=null;safe("peer-close",peer::close);safe("peer-dispose",peer::dispose);}
 private void safe(String stage,Runnable action){try{action.run();}catch(Exception error){diagnostics.record(stage,error);}}
 private void stopInternal(){signals.stop();id=null;for(Node n:peers.values())dispose(n);peers.clear();if(capture!=null){ScreenCapturerAndroid old=capture;capture=null;safe("capture-stop",old::stopCapture);safe("capture-dispose",old::dispose);}if(track!=null){VideoTrack old=track;track=null;safe("track-dispose",old::dispose);}if(source!=null){VideoSource old=source;source=null;safe("source-dispose",old::dispose);}if(helper!=null){SurfaceTextureHelper old=helper;helper=null;safe("texture-dispose",old::dispose);}}
 private void guard(Runnable action){if(closed)return;try{action.run();}catch(Exception error){peerError("screen-worker",error);}}
 private void post(Runnable action){if(closed)return;try{queue.execute(()->guard(action));}catch(RejectedExecutionException ignored){}}
 private void incoming(JSONObject envelope){try{JSONObject payload=envelope.getJSONObject("payload");if(id==null||!id.equals(payload.optString("broadcast")))return;String command=switch(payload.optString("type")){case "media-join"->"mediaJoin";case "media-recover"->"mediaRecover";case "media-leave"->"mediaLeave";case "media-heartbeat"->"mediaHeartbeat";case "media-quality"->"mediaQuality";case "native-answer"->"mediaAnswer";case "native-ice"->"mediaIce";default->null;};if(command==null)return;JSONObject args=new JSONObject(payload.toString()).put("id",id).put("viewerID",envelope.getString("sender"));JSONObject candidate=payload.optJSONObject("candidate");if(candidate!=null)for(Iterator<String> keys=candidate.keys();keys.hasNext();){String key=keys.next();args.put(key,candidate.get(key));}command(command,args);}catch(Exception error){peerError("incoming-signal",error);}}
 private void prune(JSONObject snapshot){if(id==null||scope==null)return;Set<String> allowed=new HashSet<>();try{if(scope.getString("kind").equals("direct")){JSONArray sessions=snapshot.optJSONArray("sessions");if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject session=sessions.getJSONObject(i);if(scope.getString("id").equals(session.optString("id"))&&"accepted".equals(session.optString("state"))){allowed.add(session.getString("a"));allowed.add(session.getString("b"));}}}else{String server=null;JSONArray channels=snapshot.optJSONArray("channels");if(channels!=null)for(int i=0;i<channels.length();i++){JSONObject channel=channels.getJSONObject(i);if(scope.getString("id").equals(channel.optString("id")))server=channel.getString("server_id");}JSONArray members=snapshot.optJSONArray("members");if(server!=null&&members!=null)for(int i=0;i<members.length();i++){JSONObject member=members.getJSONObject(i);if(server.equals(member.optString("server_id")))allowed.add(member.getJSONObject("profile").getString("uid"));}}for(Iterator<Node> it=peers.values().iterator();it.hasNext();){Node n=it.next();if(!allowed.contains(n.viewer)){it.remove();dispose(n);}}}catch(Exception error){peerError("permissions",error);}}
 private class Observer implements SdpObserver{final Node node;Observer(Node node){this.node=node;}public void onCreateSuccess(SessionDescription s){}public void onSetSuccess(){}private void failed(String reason){post(()->{if(peers.get(node.viewer)!=node)return;peers.remove(node.viewer);dispose(node);peerError("peer-negotiation",new Exception(reason));});}public void onCreateFailure(String reason){failed(reason);}public void onSetFailure(String reason){failed(reason);}}
}
